import { NextResponse } from "next/server"

export async function GET() {
  // 1x1 white JPEG
  const jpg = Buffer.from(
    "",
    "base64",
  )
  return new NextResponse(jpg, {
    headers: {
      "Content-Type": "image/jpeg",
      "Cache-Control": "no-cache, no-store, must-revalidate",
    },
  })
}
